export const CODE_UNRESOLVED_PATH = 71001
/** Diagnostic emitted when a component path string references an invalid export. */
export const CODE_INVALID_EXPORT = 71002

const DIAGNOSTIC_SOURCE = 'payload'

/** Type names that mark a value (or an object property) as a Payload component reference. */
const COMPONENT_TYPE_NAMES = new Set([
  'PayloadComponent',
  'RawPayloadComponent',
  'CustomComponent',
])

const RESOLVE_EXTENSIONS = ['.ts', '.tsx', '.d.ts', '.js', '.jsx', '.mjs', '.cjs']

