  /** Ordered list of export names (may include 'default'). */
  exportNames: string[]
  /** Whether the module has a default export. */
  hasDefault: boolean
  /** Map from export name -> declaration node used for go-to-definition. */
  nodes: Map<string, tslib.Node>
  /** The (possibly freshly parsed) source file for the module. */
  sourceFile: tslib.SourceFile
}

/**
