interface ComponentStringRef {
  kind: 'full' | 'objectExport' | 'objectPath'
  node: tslib.StringLiteralLike
  /** For `objectPath`: the sibling `exportName` value, if present. */
  siblingExportName?: string
  /** For `objectExport`: the sibling `path` value. */
