        /* ignore */
      }
      try {
        if (
          info.languageServiceHost &&
          typeof info.languageServiceHost.getCurrentDirectory === 'function'
        ) {
          return info.languageServiceHost.getCurrentDirectory()
        }
      } catch {
        /* ignore */
      }
      return ts.sys.getCurrentDirectory()
    }

    const projectDir = getCwd()

    const configuredBaseDir =
      info.config && typeof info.config.baseDir === 'string'
        ? path.resolve(projectDir, info.config.baseDir)
        : undefined

    const baseDir = configuredBaseDir ?? projectDir

    /** Candidate base directories for leading-slash ("/") component paths. */
    const rootBaseDirs = (): string[] => {
      const bases = [baseDir]
      if (baseDir === projectDir) {
        bases.push(path.join(projectDir, 'src'))
      }
      return bases
    }

